async (page) => {
  const checks = [];
  const unsavedTitle = '存储失败时保留在编辑器的内容-' + Date.now();
  await page.setViewportSize({width:1440,height:1000});
  const read = () => page.evaluate(() => JSON.parse(localStorage.getItem('phyqgen.prototype.v1')));
  await page.goto('http://127.0.0.1:5173/settings');
  await page.getByRole('button', { name: '编辑资料' }).click();
  await page.locator('.el-form-item').filter({ hasText: /^邮箱/ }).locator('input').fill('demo-updated@example.com');
  await page.getByRole('button', { name: '保存修改' }).click();
  await page.getByText('用户信息更新成功').waitFor();
  await page.reload();
  await page.getByText('demo-updated@example.com', { exact: true }).waitFor();
  checks.push('个人邮箱保存并刷新恢复');
  await page.getByRole('menuitem', { name: '账户安全' }).click();
  await page.getByRole('textbox', { name: /原密码/ }).fill((await read()).users.find(u => u.id === 1).password);
  await page.getByRole('textbox', { name: /新密码/ }).fill('Teacher456');
  await page.getByRole('button', { name: '修改密码', exact: true }).click();
  await page.getByText('密码修改成功', { exact: true }).waitFor();
  if ((await read()).users.find(u => u.id === 1).password !== 'Teacher456') throw new Error('密码未保存');
  checks.push('个人密码修改实际保存');
  await page.goto('http://127.0.0.1:5173/question-bank?question_id=4');
  await page.getByRole('dialog').getByRole('button', { name: '修改草稿', exact: true }).click();
  const editor = page.getByRole('dialog', { name: '教师修改习题' });
  const original = (await read()).questions.find(q => q.id === 4);
  await editor.locator('input').first().fill(unsavedTitle);
  await page.evaluate(() => { window.originalStorageSetItem = Storage.prototype.setItem; Storage.prototype.setItem = function() { throw new DOMException('Quota exceeded', 'QuotaExceededError'); }; });
  await editor.getByRole('button', { name: '保存为新版本' }).click();
  await page.getByText('本地保存失败，请检查浏览器存储空间；当前操作未保存。', { exact: true }).first().waitFor();
  if (!(await editor.isVisible()) || (await editor.locator('input').first().inputValue()) !== unsavedTitle) throw new Error('编辑器内容丢失');
  if ((await read()).questions.find(q => q.id === 4).version !== original.version) throw new Error('保存失败错误记录了新版本');
  checks.push('真实浏览器存储异常阻止保存、保留编辑内容、回滚版本');
  await page.evaluate(() => { Storage.prototype.setItem = window.originalStorageSetItem; });
  await editor.getByRole('button', { name: '保存为新版本' }).click();
  await editor.waitFor({ state: 'hidden' });
  if ((await read()).questions.find(q => q.id === 4).version !== original.version + 1) throw new Error('恢复存储后保存失败');
  checks.push('浏览器存储恢复后可重试保存');
  await page.goto('http://127.0.0.1:5173/admin/users');
  await page.waitForURL('**/overview');
  checks.push('教师访问管理员路由回到教师概览');
  await page.screenshot({ path: 'output/playwright/01-overview.png' });
  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto('http://127.0.0.1:5173/question-gen');
  await page.getByRole('heading', { name: '物理习题生成', exact: true }).waitFor();
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth > innerWidth);
  if (overflow) throw new Error('手机宽度出现横向溢出');
  await page.screenshot({ path: 'output/playwright/03-mobile-generation.png' });
  checks.push('390px移动布局无页面横向溢出');
  await page.setViewportSize({ width: 1440, height: 1000 });
  return { checks };
}
